// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // Restrict to non-zero address to avoid edge cases with zero address
        vm.assume(_newOwner != address(0));

        // Call setOwner with the fuzzed address
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", _newOwner));

        // After a successful call, owner must be _newOwner; if it reverts, owner remains unchanged (original sender)
        // The reference contract always succeeds and sets owner to _newOwner.
        // The buggy contract always reverts, so owner remains msg.sender (the test contract's address)
        // The general rule: if the call succeeds, owner is _newOwner; if it reverts, owner is unchanged.
        // For simplicity, we assert that after the call, owner equals _newOwner if success is true, otherwise it equals the original owner.
        // Since we are testing the reference, success must be true and owner must be _newOwner.
        // To make a single assertion that works for both, we use the invariant:
        // The owner after the call is either _newOwner (if no revert) or unchanged (if revert).
        // But for the reference, it always succeeds, so we assert owner == _newOwner.
        // For the mutant, it reverts, so owner != _newOwner, and the test will fail.
        assertTrue(c.owner() == _newOwner);
    }
}

